mapper.select:
WITH RECURSIVE target AS ( SELECT org_seq, org_id, parent_seq FROM tb_org WHERE org_id IN
#{orgId}
), parents AS ( SELECT org_seq FROM tb_org WHERE org_id IN
#{orgId}
), climb AS ( -- 시작은 각 지정 조직의 부모부터. 자기 자신은 세지 않는다. SELECT t.org_id, t.parent_seq AS ancestor_seq FROM target t WHERE t.parent_seq IS NOT NULL UNION ALL SELECT c.org_id, o.parent_seq FROM climb c JOIN tb_org o ON o.org_seq = c.ancestor_seq WHERE o.parent_seq IS NOT NULL ) SELECT DISTINCT c.org_id FROM climb c JOIN parents p ON p.org_seq = c.ancestor_seq ORDER BY c.org_id
